"""Peer source/primitive/GPU review; no production files are changed."""
from pathlib import Path
import hashlib,json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
native=json.loads((HERE/'independent-native-replay.json').read_text())
assert native['passed'] and native['counts']=={'folders':4,'paths':36,'selection':48}
log=(HERE/'independent-spawn-tests.log').read_text();assert '3 passed; 0 failed' in log
bindings=json.loads((HERE/'source-model-bindings.json').read_text());assert len(bindings)==20
assert {r['thing_id'] for r in bindings}=={'usa_infantry','ger_infantry','gbr_infantry','jpn_infantry','rus_infantry'}
for name in {r['thing_id'] for r in bindings}:assert sorted(r['aspect_index'] for r in bindings if r['thing_id']==name)==[0,0,1,2]
files=['crates/aa-client/src/live_spawn.rs','crates/aa-client/src/live_scene.rs','crates/aa-client/src/gpu.rs','crates/aa-client/src/inspection.rs']
evidence=['native_model_binding.py','native-model-binding.json','source-model-bindings.json','independent-native-replay.json','independent-spawn-tests.log','record_independent_review.py']
report={'schema':1,'passed':True,'reviewer':'core_review; read-only peer acceptance of material_render spawn scope','scope':'Source-resolved static actor spawn, staged GPU/picking publication, duplicate/epoch/failure behavior. Existing animation integration is not covered.','native_replayed':native['counts'],'source_bindings':20,'source_nations':5,'source_aspects_per_nation':3,'rust_tests':3,'command':['cargo','test','-p','aa-client','--release','live_scene::spawn','--','--include-ignored','--nocapture'],'environment':{'AA_GAME_ROOT':str(ROOT.parent)},'exit_code':0,'source_sha256':{p:sha(ROOT/p) for p in files},'evidence_sha256':{p:sha(HERE/p) for p in evidence},'native_original_sha256':native['original_sha256'],'native_v14_sha256':native['v14_sha256'],'findings':[],'reviewed':['Source Thing/normal-aspect identity resolves by source View/Aspect metadata with caller-supplied actual state/construction aspect. No arbitrary model fallback.','Only supported one-string model formatting and safe relative resource paths accepted; skin/glow/TextureRename remain explicit unsupported errors.','GPU prepare_upload uses staged resources and does not mutate current draws; append offsets preserve old draw slots, epoch and cached mesh buffers.','Picking data staged and capacity checked before GPU acceptance; duplicate IDs and stale epochs reject without publishing CPU bindings.','Visibility changes update GPU and picking together; ray probe selects the visible newly published mesh and stops selecting it when hidden.','Malformatted mip chain fails after picking preparation but before current scene publication, preserving prior pixels/accounting.'],'visual_inspection':{'visible':'qa-output/phase7/live-spawn/visible.png','hidden':'qa-output/phase7/live-spawn/hidden.png','observation':'Lifted/scaled original infantry visible only in visible probe. The probe verifies presentation insertion, not native battlefield scale or pose parity.'},'limitations':['Ordinary source binding for the five infantry definitions and their three aspects only; source IDs/aspect resolution remain caller responsibilities.','Path oracle is original46A9AF..46AA2C fragment; string/format leaves supplied,85A030 parent normalization not replayed.','Native aspect selection has explicit actor/state-presence seams; unsupported construction/state aspect must be supplied by actual runtime.','GPU append order is caller publication order, not claimed native scene insertion parity.','No native gameplay spawning, full original animation, command handling, combat or match claim.','System allocator termination and device loss are outside transactional rollback guarantees.','Review does not assert a fresh all-target Clippy run; owner records that separate check.']}
path=HERE/'independent-review.json';path.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'passed':True,'sha256':sha(path)}))
